I would like to be able to use a flake with a simple `symlinkJoin` package:

```
{
  description = "dotfiles";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixpkgs-unstable";
    systems.url = "github:nix-systems/default";
  };

  outputs = inputs@{ nixpkgs, systems, ... }: let
    forAllSystems = fn:
      nixpkgs.lib.genAttrs (import systems) (system: fn {
        pkgs = nixpkgs.legacyPackages.${system};
        inherit system;
      });
    in {
      packages = forAllSystems ({ pkgs, ... }: {
        default = pkgs.symlinkJoin {
          name = "pkgs";
          paths = with pkgs; [
            # Tools
            yash
            neovim
            zoxide
            gopls
            zellij
            lazygit
            ripgrep
            tealdeer
            pandoc          # For markdown
            texliveMinimal #
            eza

            # Language servers
            lua-language-server
            nixd
            marksman
            ltex-ls

            # Languages
            hare
            harec
            rustup

          ];
        };
      });
    };
}
```

However when I build this the `result/` symlink does not seem to be reachable, I assume this is a namespacing issue as it is only not reachable because it points to `/nix/store` explicitly.

Additionally if I `nix profile install`, this works however I cannot `. $HOME/.nix-profile/etc/profile.d/nix.sh`

```bash
NP_RUNTIME=bwrap ./nix-portable nix-shell --run "bash" --cores 4 -j4 --pure ci/shell.nix
```
With the following `ci/shell.nix`:
```nix
{ clangOnly ? "no" }:
let
  sources = import ./nix/sources.nix;
  pkgs = import sources.nixpkgs { };
  mach-nix = import (builtins.fetchGit {
    url = "https://github.com/DavHau/mach-nix/";
    ref = "refs/tags/3.1.1";
  }) {
    pkgs = pkgs;
    python = "python37";
  };
  customPython = mach-nix.mkPython rec {
    requirements = ''
      pytest
      toml
    '';
  };
  llvmPkgs = pkgs.buildPackages.llvmPackages_11;
  myStdenv = if clangOnly=="yes" then llvmPkgs.stdenv else pkgs.gcc10Stdenv;
  myBinutils = if clangOnly=="yes" then llvmPkgs.bintools else pkgs.binutils;
  mkShellNewEnv = pkgs.mkShell.override { stdenv = myStdenv; };
in mkShellNewEnv {
  nativeBuildInputs = [ pkgs.cmake ];
  buildInputs = with pkgs; [
    customPython
    bashInteractive
    which
    gfortran
    valgrind
    gdb
    fmt
    llvm_11
    lld_11
    myBinutils
    bison_3_5
    zlib
    libbfd
    re2c
    git
    xonsh
    rapidjson
  ];
}
```
